@Override public void load(){super.load();cm=(CameraManager)getContext().getSystemService(Context.CAMERA_SERVICE);th=new HandlerThread("MG30-Camera2");th.start();h=new Handler(th.getLooper());}
@PluginMethod public void listCameras(PluginCall c){try{JSArray a=new JSArray();for(String id:cm.getCameraIdList()){CameraCharacteristics k=cm.getCameraCharacteristics(id);Integer f=k.get(CameraCharacteristics.LENS_FACING);JSObject o=new JSObject();o.put("id",id);o.put("facing",f!=null&&f==CameraCharacteristics.LENS_FACING_FRONT?"front":"back");o.put("noiseReductionOffSupported",has(k.get(CameraCharacteristics.NOISE_REDUCTION_AVAILABLE_NOISE_REDUCTION_MODES),CaptureRequest.NOISE_REDUCTION_MODE_OFF));o.put("edgeOffSupported",has(k.get(CameraCharacteristics.EDGE_AVAILABLE_EDGE_MODES),CaptureRequest.EDGE_MODE_OFF));a.put(o);}JSObject o=new JSObject();o.put("cameras",a);c.resolve(o);}catch(Exception e){c.reject(msg(e));}}
@PluginMethod public void openPreview(PluginCall c){if(getPermissionState("camera")!=PermissionState.GRANTED){requestPermissionForAlias("camera",c,"cameraPerm");return;}openGranted(c);}
@PermissionCallback private void cameraPerm(PluginCall c){if(getPermissionState("camera")==PermissionState.GRANTED)openGranted(c);else c.reject("Izin kamera tidak diberikan.");}
void openGranted(PluginCall c){if(recording){c.reject("Hentikan rekaman terlebih dahulu.");return;}wantFront="front".equalsIgnoreCase(c.getString("facing","back"));bounds(c);openCall=c;last="";getActivity().runOnUiThread(()->{try{attach();if(tv.isAvailable())onSurfaceTextureAvailable(tv.getSurfaceTexture(),tv.getWidth(),tv.getHeight());}catch(Exception e){rejectOpen(msg(e));closeAll();}});}
@PluginMethod public void updatePreviewBounds(PluginCall c){bounds(c);getActivity().runOnUiThread(this::layout);JSObject o=new JSObject();o.put("updated",true);c.resolve(o);}
void bounds(PluginCall c){left=Math.max(0,c.getInt("left",0));top=Math.max(0,c.getInt("top",0));width=Math.max(1,c.getInt("width",320));height=Math.max(1,c.getInt("height",220));}
int px(int v){return Math.round(v*getContext().getResources().getDisplayMetrics().density);}
void attach(){if(tv!=null){layout();return;}View v=getActivity().findViewById(android.R.id.content);if(!(v instanceof FrameLayout))throw new IllegalStateException("Preview container tidak ada");root=(FrameLayout)v;tv=new TextureView(getContext());tv.setSurfaceTextureListener(this);tv.setClickable(false);tv.setFocusable(false);root.addView(tv,new FrameLayout.LayoutParams(px(width),px(height)));layout();}
void layout(){if(tv==null)return;FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(px(width),px(height));p.leftMargin=px(left);p.topMargin=px(top);tv.setLayoutParams(p);tv.bringToFront();}
@Override public void onSurfaceTextureAvailable(SurfaceTexture st,int w,int h){if(dev!=null||opening)return;try{openCam();}catch(Exception e){rejectOpen(msg(e));closeAll();}}
void openCam()throws Exception{String chosen=null,fb=null;for(String id:cm.getCameraIdList()){CameraCharacteristics k=cm.getCameraCharacteristics(id);Integer f=k.get(CameraCharacteristics.LENS_FACING);boolean isf=f!=null&&f==CameraCharacteristics.LENS_FACING_FRONT;if(fb==null)fb=id;if(isf==wantFront){chosen=id;break;}}if(chosen==null)chosen=fb;if(chosen==null)throw new IllegalStateException("Tidak ada kamera");cameraId=chosen;ch=cm.getCameraCharacteristics(chosen);Integer f=ch.get(CameraCharacteristics.LENS_FACING);front=f!=null&&f==CameraCharacteristics.LENS_FACING_FRONT;StreamConfigurationMap map=ch.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);if(map==null)throw new IllegalStateException("Stream Camera2 tidak tersedia");Size v=videoSize(map.getOutputSizes(MediaRecorder.class)),p=previewSize(map.getOutputSizes(SurfaceTexture.class),v);vw=v.getWidth();vh=v.getHeight();tv.getSurfaceTexture().setDefaultBufferSize(p.getWidth(),p.getHeight());preview=new Surface(tv.getSurfaceTexture());opening=true;cm.openCamera(chosen,new CameraDevice.StateCallback(){@Override public void onOpened(CameraDevice d){opening=false;dev=d;configure(false,null);}@Override public void onDisconnected(CameraDevice d){d.close();dev=null;notifyListeners("cameraError",event("Kamera terputus"));rejectOpen("Kamera terputus");if(!recording)closeAll();}@Override public void onError(CameraDevice d,int e){d.close();dev=null;notifyListeners("cameraError",event("Camera2 error "+e));rejectOpen("Camera2 error "+e);closeAll();}},h);}
@PluginMethod public void startRecording(PluginCall c){if(dev==null||preview==null||recording){c.reject("Aktifkan preview kamera sebelum merekam.");return;}try{String t=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date());file=new File(dir(),"MG30_Video_"+t+".mp4");mr=new MediaRecorder();mr.setVideoSource(MediaRecorder.VideoSource.SURFACE);mr.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);mr.setOutputFile(file.getAbsolutePath());mr.setVideoEncoder(MediaRecorder.VideoEncoder.H264);mr.setVideoSize(vw,vh);mr.setVideoFrameRate(30);mr.setVideoEncodingBitRate(vw*vh>=2073600?12000000:8000000);mr.setOrientationHint(orientation());mr.prepare();enc=mr.getSurface();if(ss!=null){ss.close();ss=null;}configure(true,c);}catch(Exception e){releaseMr();if(file!=null&&file.exists()&&file.length()==0)file.delete();file=null;c.reject("Gagal menyiapkan video: "+msg(e));configure(false,null);}}
@PluginMethod public void stopRecording(PluginCall c){if(!recording||mr==null||file==null){c.reject("Tidak ada rekaman aktif.");return;}try{JSObject o=finish();configure(false,null);c.resolve(o);}catch(Exception e){releaseMr();recording=false;c.reject("Gagal menyimpan video: "+msg(e));configure(false,null);}}
@PluginMethod public void closePreview(PluginCall c){JSObject stopped=null;if(recording&&mr!=null&&file!=null)try{stopped=finish();}catch(Exception e){releaseMr();recording=false;notifyListeners("cameraError",event(msg(e)));}closeAll();JSObject o=new JSObject();o.put("closed",true);if(stopped!=null)o.put("stoppedRecording",stopped);c.resolve(o);}
@PluginMethod public void listRecordings(PluginCall c){File[] a=dir().listFiles((d,n)->n.toLowerCase(Locale.ROOT).endsWith(".mp4"));if(a==null)a=new File[0];Arrays.sort(a,Comparator.comparingLong(File::lastModified).reversed());JSArray outA=new JSArray();for(File f:a)if(f.isFile()&&f.length()>1024){JSObject o=new JSObject();o.put("path",f.getAbsolutePath());o.put("fileName",f.getName());o.put("sizeBytes",f.length());o.put("lastModified",f.lastModified());outA.put(o);}JSObject o=new JSObject();o.put("recordings",outA);c.resolve(o);}
@PluginMethod public void renameRecording(PluginCall c){File f=owned(c.getString("path",""));if(f==null||!f.exists()){c.reject("File tidak ditemukan.");return;}String n=c.getString("name","").trim().replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");if(n.isEmpty()){c.reject("Nama kosong.");return;}if(!n.toLowerCase(Locale.ROOT).endsWith(".mp4"))n+=".mp4";File d=new File(dir(),n);if(d.exists()){c.reject("Nama sudah dipakai.");return;}if(!f.renameTo(d)){c.reject("Gagal mengganti nama.");return;}JSObject o=new JSObject();o.put("path",d.getAbsolutePath());o.put("fileName",d.getName());o.put("sizeBytes",d.length());o.put("lastModified",d.lastModified());c.resolve(o);}
void configure(boolean video,PluginCall start){if(dev==null||preview==null){if(start!=null)start.reject("Kamera belum siap");return;}try{List<Surface> outs=new ArrayList<>();outs.add(preview);if(video){if(enc==null)throw new IllegalStateException("Encoder belum siap");outs.add(enc);}dev.createCaptureSession(outs,new CameraCaptureSession.StateCallback(){@Override public void onConfigured(CameraCaptureSession s){ss=s;try{CaptureRequest.Builder b=dev.createCaptureRequest(video?CameraDevice.TEMPLATE_RECORD:CameraDevice.TEMPLATE_PREVIEW);b.addTarget(preview);if(video)b.addTarget(enc);controls(b);s.setRepeatingRequest(b.build(),new CameraCaptureSession.CaptureCallback(){@Override public void onCaptureCompleted(CameraCaptureSession q,CaptureRequest r,TotalCaptureResult result){report(result,video);}@Override public void onCaptureFailed(CameraCaptureSession q,CaptureRequest r,CaptureFailure f){notifyListeners("cameraError",event("Capture gagal: "+f.getReason()));}},h);if(video){mr.start();recording=true;started=System.currentTimeMillis();JSObject o=info();o.put("recording",true);o.put("fileName",file.getName());o.put("videoWidth",vw);o.put("videoHeight",vh);start.resolve(o);}else if(openCall!=null){PluginCall p=openCall;openCall=null;JSObject o=info();o.put("previewReady",true);p.resolve(o);}}catch(Exception e){if(start!=null)start.reject("Camera2 gagal: "+msg(e));rejectOpen(msg(e));notifyListeners("cameraError",event(msg(e)));}}@Override public void onConfigureFailed(CameraCaptureSession s){s.close();if(start!=null)start.reject("Konfigurasi kamera gagal");rejectOpen("Preview gagal dikonfigurasi");}},h);}catch(Exception e){if(start!=null)start.reject(msg(e));rejectOpen(msg(e));}}
void controls(CaptureRequest.Builder b){int[] af=ch.get(CameraCharacteristics.CONTROL_AF_AVAILABLE_MODES);if(has(af,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_VIDEO))b.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_VIDEO);else if(has(af,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE))b.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);int[] ae=ch.get(CameraCharacteristics.CONTROL_AE_AVAILABLE_MODES);if(has(ae,CaptureRequest.CONTROL_AE_MODE_ON))b.set(CaptureRequest.CONTROL_AE_MODE,CaptureRequest.CONTROL_AE_MODE_ON);int[] awb=ch.get(CameraCharacteristics.CONTROL_AWB_AVAILABLE_MODES);if(has(awb,CaptureRequest.CONTROL_AWB_MODE_AUTO))b.set(CaptureRequest.CONTROL_AWB_MODE,CaptureRequest.CONTROL_AWB_MODE_AUTO);Range<Integer>[] ranges=ch.get(CameraCharacteristics.CONTROL_AE_AVAILABLE_TARGET_FPS_RANGES);if(ranges!=null){Range<Integer> best=null;int score=9999;for(Range<Integer> r:ranges)if(r.getLower()<=30&&r.getUpper()>=30){int s=Math.abs(r.getLower()-30)+Math.abs(r.getUpper()-30);if(s<score){score=s;best=r;}}if(best!=null)b.set(CaptureRequest.CONTROL_AE_TARGET_FPS_RANGE,best);}if(has(ch.get(CameraCharacteristics.NOISE_REDUCTION_AVAILABLE_NOISE_REDUCTION_MODES),CaptureRequest.NOISE_REDUCTION_MODE_OFF))b.set(CaptureRequest.NOISE_REDUCTION_MODE,CaptureRequest.NOISE_REDUCTION_MODE_OFF);if(has(ch.get(CameraCharacteristics.EDGE_AVAILABLE_EDGE_MODES),CaptureRequest.EDGE_MODE_OFF))b.set(CaptureRequest.EDGE_MODE,CaptureRequest.EDGE_MODE_OFF);if(has(ch.get(CameraCharacteristics.COLOR_CORRECTION_AVAILABLE_ABERRATION_MODES),CaptureRequest.COLOR_CORRECTION_ABERRATION_MODE_OFF))b.set(CaptureRequest.COLOR_CORRECTION_ABERRATION_MODE,CaptureRequest.COLOR_CORRECTION_ABERRATION_MODE_OFF);if(android.os.Build.VERSION.SDK_INT>=28&&has(ch.get(CameraCharacteristics.DISTORTION_CORRECTION_AVAILABLE_MODES),CaptureRequest.DISTORTION_CORRECTION_MODE_OFF))b.set(CaptureRequest.DISTORTION_CORRECTION_MODE,CaptureRequest.DISTORTION_CORRECTION_MODE_OFF);}
void report(CaptureResult r,boolean video){Integer nr=r.get(CaptureResult.NOISE_REDUCTION_MODE),ed=r.get(CaptureResult.EDGE_MODE);String key=video+":"+nr+":"+ed;if(key.equals(last))return;last=key;JSObject o=new JSObject();o.put("pipeline",video?"recording":"preview");o.put("noiseReductionMode",nr);o.put("edgeMode",ed);o.put("noiseReductionOffSupported",has(ch.get(CameraCharacteristics.NOISE_REDUCTION_AVAILABLE_NOISE_REDUCTION_MODES),CaptureRequest.NOISE_REDUCTION_MODE_OFF));o.put("edgeOffSupported",has(ch.get(CameraCharacteristics.EDGE_AVAILABLE_EDGE_MODES),CaptureRequest.EDGE_MODE_OFF));o.put("noiseReductionStatus",nr==null?"Tidak dapat diverifikasi":nr==0?"OFF diterapkan":"Mode aktif: "+nr);o.put("edgeStatus",ed==null?"Tidak dapat diverifikasi":ed==0?"OFF diterapkan":"Mode aktif: "+ed);notifyListeners("processingStatus",o);}
JSObject info(){JSObject o=new JSObject();o.put("cameraId",cameraId);o.put("facing",front?"front":"back");o.put("noiseReductionOffSupported",has(ch.get(CameraCharacteristics.NOISE_REDUCTION_AVAILABLE_NOISE_REDUCTION_MODES),CaptureRequest.NOISE_REDUCTION_MODE_OFF));o.put("edgeOffSupported",has(ch.get(CameraCharacteristics.EDGE_AVAILABLE_EDGE_MODES),CaptureRequest.EDGE_MODE_OFF));o.put("videoWidth",vw);o.put("videoHeight",vh);return o;}
JSObject finish()throws IOException{File f=file;RuntimeException error=null;try{mr.stop();}catch(RuntimeException e){error=e;}releaseMr();recording=false;long duration=Math.max(0,System.currentTimeMillis()-started);if(ss!=null){try{ss.close();}catch(Exception ignored){}ss=null;}if(error!=null||f==null||!f.exists()||f.length()<1024){if(f!=null&&f.exists())f.delete();file=null;throw new IOException("Video tidak valid/terlalu pendek; rekam minimal 2 detik");}JSObject o=new JSObject();o.put("path",f.getAbsolutePath());o.put("fileName",f.getName());o.put("sizeBytes",f.length());o.put("lastModified",f.lastModified());o.put("durationMs",duration);o.put("videoWidth",vw);o.put("videoHeight",vh);file=null;started=0;return o;}
void releaseMr(){if(enc!=null){try{enc.release();}catch(Exception ignored){}enc=null;}if(mr!=null){try{mr.reset();}catch(Exception ignored){}try{mr.release();}catch(Exception ignored){}mr=null;}}
int orientation(){int r=getActivity().getWindowManager().getDefaultDisplay().getRotation();int deg=r==Surface.ROTATION_90?90:r==Surface.ROTATION_180?180:r==Surface.ROTATION_270?270:0;Integer s=ch.get(CameraCharacteristics.SENSOR_ORIENTATION);int sd=s==null?0:s;return front?(sd-deg+360)%360:(sd+deg)%360;}
File dir(){File ext=getContext().getExternalFilesDir(Environment.DIRECTORY_MOVIES);File d=new File(ext==null?getContext().getFilesDir():ext,"MG30Studio");if(!d.exists())d.mkdirs();return d;}
File owned(String path){try{File base=dir().getCanonicalFile(),f=new File(path==null?"":path).getCanonicalFile();return f.getParentFile()!=null&&f.getParentFile().equals(base)&&f.getName().toLowerCase(Locale.ROOT).endsWith(".mp4")?f:null;}catch(IOException e){return null;}}
void closeAll(){if(ss!=null){try{ss.stopRepeating();}catch(Exception ignored){}try{ss.close();}catch(Exception ignored){}ss=null;}if(dev!=null){try{dev.close();}catch(Exception ignored){}dev=null;}opening=false;if(preview!=null){try{preview.release();}catch(Exception ignored){}preview=null;}rejectOpen("Preview ditutup");try{getActivity().runOnUiThread(()->{if(tv!=null){tv.setSurfaceTextureListener(null);if(root!=null)root.removeView(tv);tv=null;}root=null;});}catch(Exception ignored){}}
