JSObject event(String m){JSObject o=new JSObject();o.put("message",m);return o;}
static boolean has(int[] a,int n){if(a==null)return false;for(int i:a)if(i==n)return true;return false;}
static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
static Size videoSize(Size[] ss){if(ss==null||ss.length==0)return new Size(1280,720);Size best=null;double score=Double.MAX_VALUE;for(Size s:ss){if(s.getWidth()<640||s.getHeight()<360)continue;double r=Math.abs(s.getWidth()/(double)s.getHeight()-16.0/9),v=r*100000+(s.getWidth()<=1920&&s.getHeight()<=1080?-(double)s.getWidth()*s.getHeight()/100:100000+(double)s.getWidth()*s.getHeight());if(v<score){score=v;best=s;}}return best==null?ss[0]:best;}
static Size previewSize(Size[] ss,Size v){if(ss==null||ss.length==0)return v;Size b=ss[0];double score=Double.MAX_VALUE,ratio=v.getWidth()/(double)v.getHeight();for(Size s:ss){double q=Math.abs(s.getWidth()/(double)s.getHeight()-ratio)*100000+Math.abs((long)s.getWidth()*s.getHeight()-(long)v.getWidth()*v.getHeight())/1000.0;if(q<score){score=q;b=s;}}return b;}
@Override public void onSurfaceTextureSizeChanged(SurfaceTexture s,int w,int h){layout();}@Override public boolean onSurfaceTextureDestroyed(SurfaceTexture s){return true;}@Override public void onSurfaceTextureUpdated(SurfaceTexture s){}
@Override protected void handleOnPause(){super.handleOnPause();if(recording&&mr!=null&&file!=null)try{JSObject o=finish();notifyListeners("recordingInterrupted",o);}catch(Exception e){releaseMr();recording=false;notifyListeners("cameraError",event(msg(e)));}closeAll();}
